/**
 * Bootstrap 5.3.0 - Essential Components for Teddy Bear Shop
 * Simplified version with core functionality
 */

(function() {
    'use strict';

    // Dropdown functionality
    class Dropdown {
        constructor(element) {
            this.element = element;
            this.menu = element.nextElementSibling;
            this.isOpen = false;
            this.init();
        }

        init() {
            this.element.addEventListener('click', (e) => {
                e.preventDefault();
                this.toggle();
            });

            document.addEventListener('click', (e) => {
                if (!this.element.contains(e.target) && !this.menu.contains(e.target)) {
                    this.hide();
                }
            });
        }

        toggle() {
            this.isOpen ? this.hide() : this.show();
        }

        show() {
            this.menu.classList.add('show');
            this.element.setAttribute('aria-expanded', 'true');
            this.isOpen = true;
        }

        hide() {
            this.menu.classList.remove('show');
            this.element.setAttribute('aria-expanded', 'false');
            this.isOpen = false;
        }
    }

    // Modal functionality
    class Modal {
        constructor(element) {
            this.element = element;
            this.backdrop = null;
            this.isOpen = false;
            this.init();
        }

        init() {
            const triggers = document.querySelectorAll(`[data-bs-toggle="modal"][data-bs-target="#${this.element.id}"]`);
            triggers.forEach(trigger => {
                trigger.addEventListener('click', () => this.show());
            });

            const closeButtons = this.element.querySelectorAll('[data-bs-dismiss="modal"]');
            closeButtons.forEach(button => {
                button.addEventListener('click', () => this.hide());
            });
        }

        show() {
            if (this.isOpen) return;

            this.createBackdrop();
            this.element.style.display = 'block';
            this.element.classList.add('show');
            document.body.classList.add('modal-open');
            this.isOpen = true;

            // Trigger shown event
            this.element.dispatchEvent(new Event('shown.bs.modal'));
        }

        hide() {
            if (!this.isOpen) return;

            this.element.classList.remove('show');
            setTimeout(() => {
                this.element.style.display = 'none';
                this.removeBackdrop();
                document.body.classList.remove('modal-open');
            }, 150);
            this.isOpen = false;

            // Trigger hidden event
            this.element.dispatchEvent(new Event('hidden.bs.modal'));
        }

        createBackdrop() {
            this.backdrop = document.createElement('div');
            this.backdrop.className = 'modal-backdrop fade show';
            document.body.appendChild(this.backdrop);
            
            this.backdrop.addEventListener('click', () => this.hide());
        }

        removeBackdrop() {
            if (this.backdrop) {
                this.backdrop.remove();
                this.backdrop = null;
            }
        }
    }

    // Collapse functionality
    class Collapse {
        constructor(element) {
            this.element = element;
            this.isOpen = element.classList.contains('show');
            this.init();
        }

        init() {
            const triggers = document.querySelectorAll(`[data-bs-toggle="collapse"][data-bs-target="#${this.element.id}"]`);
            triggers.forEach(trigger => {
                trigger.addEventListener('click', () => this.toggle());
            });
        }

        toggle() {
            this.isOpen ? this.hide() : this.show();
        }

        show() {
            if (this.isOpen) return;
            
            this.element.style.height = '0px';
            this.element.classList.add('collapsing');
            this.element.classList.remove('collapse');
            
            const height = this.element.scrollHeight;
            this.element.style.height = height + 'px';
            
            setTimeout(() => {
                this.element.classList.remove('collapsing');
                this.element.classList.add('collapse', 'show');
                this.element.style.height = '';
                this.isOpen = true;
            }, 350);
        }

        hide() {
            if (!this.isOpen) return;
            
            this.element.style.height = this.element.scrollHeight + 'px';
            this.element.classList.add('collapsing');
            this.element.classList.remove('collapse', 'show');
            
            setTimeout(() => {
                this.element.style.height = '0px';
            }, 10);
            
            setTimeout(() => {
                this.element.classList.remove('collapsing');
                this.element.classList.add('collapse');
                this.element.style.height = '';
                this.isOpen = false;
            }, 350);
        }
    }

    // Tab functionality
    class Tab {
        constructor(element) {
            this.element = element;
            this.target = document.querySelector(element.getAttribute('data-bs-target') || element.getAttribute('href'));
            this.init();
        }

        init() {
            this.element.addEventListener('click', (e) => {
                e.preventDefault();
                this.show();
            });
        }

        show() {
            // Hide all other tabs in the same group
            const tabGroup = this.element.closest('.nav');
            if (tabGroup) {
                const allTabs = tabGroup.querySelectorAll('[data-bs-toggle="tab"], [data-bs-toggle="pill"]');
                allTabs.forEach(tab => {
                    tab.classList.remove('active');
                    const target = document.querySelector(tab.getAttribute('data-bs-target') || tab.getAttribute('href'));
                    if (target) {
                        target.classList.remove('show', 'active');
                    }
                });
            }

            // Show current tab
            this.element.classList.add('active');
            if (this.target) {
                this.target.classList.add('show', 'active');
            }
        }
    }

    // Tooltip functionality
    class Tooltip {
        constructor(element) {
            this.element = element;
            this.tooltip = null;
            this.title = element.getAttribute('data-bs-title') || element.getAttribute('title');
            this.init();
        }

        init() {
            this.element.addEventListener('mouseenter', () => this.show());
            this.element.addEventListener('mouseleave', () => this.hide());
        }

        show() {
            if (!this.title) return;

            this.tooltip = document.createElement('div');
            this.tooltip.className = 'tooltip bs-tooltip-top fade show';
            this.tooltip.innerHTML = `
                <div class="tooltip-arrow"></div>
                <div class="tooltip-inner">${this.title}</div>
            `;

            document.body.appendChild(this.tooltip);
            this.position();
        }

        hide() {
            if (this.tooltip) {
                this.tooltip.remove();
                this.tooltip = null;
            }
        }

        position() {
            if (!this.tooltip) return;

            const rect = this.element.getBoundingClientRect();
            const tooltipRect = this.tooltip.getBoundingClientRect();

            this.tooltip.style.position = 'absolute';
            this.tooltip.style.left = (rect.left + rect.width / 2 - tooltipRect.width / 2) + 'px';
            this.tooltip.style.top = (rect.top - tooltipRect.height - 5) + 'px';
        }
    }

    // Alert functionality
    class Alert {
        constructor(element) {
            this.element = element;
            this.init();
        }

        init() {
            const closeButton = this.element.querySelector('[data-bs-dismiss="alert"]');
            if (closeButton) {
                closeButton.addEventListener('click', () => this.close());
            }
        }

        close() {
            this.element.classList.add('fade');
            setTimeout(() => {
                this.element.remove();
            }, 150);
        }
    }

    // Initialize all components
    function initBootstrap() {
        // Dropdowns
        document.querySelectorAll('[data-bs-toggle="dropdown"]').forEach(element => {
            new Dropdown(element);
        });

        // Modals
        document.querySelectorAll('.modal').forEach(element => {
            new Modal(element);
        });

        // Collapse
        document.querySelectorAll('.collapse').forEach(element => {
            new Collapse(element);
        });

        // Tabs
        document.querySelectorAll('[data-bs-toggle="tab"], [data-bs-toggle="pill"]').forEach(element => {
            new Tab(element);
        });

        // Tooltips
        document.querySelectorAll('[data-bs-toggle="tooltip"]').forEach(element => {
            new Tooltip(element);
        });

        // Alerts
        document.querySelectorAll('.alert').forEach(element => {
            new Alert(element);
        });
    }

    // Auto-initialize when DOM is loaded
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initBootstrap);
    } else {
        initBootstrap();
    }

    // Global Bootstrap object
    window.bootstrap = {
        Dropdown,
        Modal,
        Collapse,
        Tab,
        Tooltip,
        Alert
    };

})();